    (SELECT COUNT_IF(NOT shs_master_teacher_iv_unavailable) FROM c) AS all_blank_measure_unflagged,
    (SELECT COUNT_IF(shs_principal_total_discrepancy) FROM c) AS principal_discrepancies,
        (SELECT COUNT_IF(b.sector IS NOT NULL AND b.sector <> '' AND b.sector NOT IN ('Public', 'Private', 'SUC/LUC', 'PSO')) FROM bronze AS b) AS unmapped_sector,
        (SELECT COUNT_IF(b.school_management IS NOT NULL AND b.school_management <> '' AND b.school_management NOT IN ('DepEd', 'Non-Sectarian', 'Sectarian', 'SUC', 'LUC', 'DOST', 'Other GA', 'International School', 'PSO')) FROM bronze AS b) AS unmapped_school_management,
        (SELECT COUNT_IF(b.offers_es IS NOT NULL AND b.offers_es <> '' AND b.offers_es NOT IN ('True', 'False')) FROM bronze AS b) AS unmapped_offers_es,
        (SELECT COUNT_IF(b.offers_jhs IS NOT NULL AND b.offers_jhs <> '' AND b.offers_jhs NOT IN ('True', 'False')) FROM bronze AS b) AS unmapped_offers_jhs,
        (SELECT COUNT_IF(b.offers_shs IS NOT NULL AND b.offers_shs <> '' AND b.offers_shs NOT IN ('True', 'False')) FROM bronze AS b) AS unmapped_offers_shs
), quarantine_counts AS (
  SELECT
    COALESCE(COUNT_IF(array_contains(q.quarantine_reasons, 'school_id_blank')), 0) AS school_id_blank,
    COALESCE(COUNT_IF(array_contains(q.quarantine_reasons, 'school_id_malformed')), 0) AS school_id_malformed,
    COALESCE(COUNT_IF(array_contains(q.quarantine_reasons, 'school_id_duplicated')), 0) AS school_id_duplicated,
    COALESCE(COUNT_IF(array_contains(q.quarantine_reasons, 'measure_negative')), 0) AS measure_negative,
    COALESCE(COUNT_IF(array_contains(q.quarantine_reasons, 'measure_uncastable')), 0) AS measure_uncastable,
    COALESCE(COUNT_IF(array_contains(q.quarantine_reasons, 'measure_above_int_max')), 0) AS measure_above_int_max,
    COALESCE(COUNT_IF(array_contains(q.quarantine_reasons, 'measure_outside_public_scope')), 0) AS measure_outside_public_scope,
    COALESCE(COUNT_IF(array_contains(q.quarantine_reasons, 'measure_outside_offered_level')), 0) AS measure_outside_offered_level
  FROM q
)
SELECT cur.batch_id, counts.*, quarantine_counts.* FROM cur CROSS JOIN counts CROSS JOIN quarantine_counts;

ALTER TABLE edu_access.`03-silver`.deped_personnel_gate_summary_candidate OWNER TO `reached-hq`;

INSERT INTO edu_access.`01-control`.data_quality_results (run_id, batch_id, source_id, layer, table_name, check_name, status, expected, actual, checked_at_utc, code_revision)
SELECT :run_id, batch_id, 'deped_personnel', 'silver', table_name, check_name, status, expected, actual, current_timestamp(), :code_revision FROM (
SELECT batch_id, 'edu_access.03-silver.deped_personnel_clean_candidate' AS table_name, 'current_batch_present' AS check_name, CASE WHEN current_batches > 0 THEN 'PASS' ELSE 'FAIL' END AS status, '> 0' AS expected, CAST(current_batches AS STRING) AS actual FROM edu_access.`03-silver`.deped_personnel_gate_summary_candidate
  UNION ALL SELECT batch_id, 'edu_access.03-silver.deped_personnel_clean_candidate' AS table_name, 'rows_reconcile' AS check_name, CASE WHEN clean_rows + quarantine_rows = bronze_rows THEN 'PASS' ELSE 'FAIL' END AS status, '= bronze_rows' AS expected, CAST(clean_rows + quarantine_rows AS STRING) AS actual FROM edu_access.`03-silver`.deped_personnel_gate_summary_candidate
  UNION ALL SELECT batch_id, 'edu_access.03-silver.deped_personnel_clean_candidate' AS table_name, 'school_id_unique' AS check_name, CASE WHEN duplicate_clean_ids = 0 THEN 'PASS' ELSE 'FAIL' END AS status, '= 0' AS expected, CAST(duplicate_clean_ids AS STRING) AS actual FROM edu_access.`03-silver`.deped_personnel_gate_summary_candidate
  UNION ALL SELECT batch_id, 'edu_access.03-silver.deped_personnel_clean_candidate' AS table_name, 'lineage_complete' AS check_name, CASE WHEN missing_lineage = 0 THEN 'PASS' ELSE 'FAIL' END AS status, '= 0' AS expected, CAST(missing_lineage AS STRING) AS actual FROM edu_access.`03-silver`.deped_personnel_gate_summary_candidate
  UNION ALL SELECT batch_id, 'edu_access.03-silver.deped_personnel_clean_candidate' AS table_name, 'rows_built_by_this_run' AS check_name, CASE WHEN other_run_rows = 0 THEN 'PASS' ELSE 'FAIL' END AS status, '= 0' AS expected, CAST(other_run_rows AS STRING) AS actual FROM edu_access.`03-silver`.deped_personnel_gate_summary_candidate
  UNION ALL SELECT batch_id, 'edu_access.03-silver.deped_personnel_clean_candidate' AS table_name, 'blank_measures_stay_null' AS check_name, CASE WHEN silver_null_measures = bronze_blank_measures THEN 'PASS' ELSE 'FAIL' END AS status, '= bronze_blank_measures' AS expected, CAST(silver_null_measures AS STRING) AS actual FROM edu_access.`03-silver`.deped_personnel_gate_summary_candidate
  UNION ALL SELECT batch_id, 'edu_access.03-silver.deped_personnel_clean_candidate' AS table_name, 'recorded_zero_preserved' AS check_name, CASE WHEN silver_zero_measures = bronze_zero_measures THEN 'PASS' ELSE 'FAIL' END AS status, '= bronze_zero_measures' AS expected, CAST(silver_zero_measures AS STRING) AS actual FROM edu_access.`03-silver`.deped_personnel_gate_summary_candidate
  UNION ALL SELECT batch_id, 'edu_access.03-silver.deped_personnel_clean_candidate' AS table_name, 'all_blank_measure_retained' AS check_name, CASE WHEN all_blank_measure_non_null = 0 THEN 'PASS' ELSE 'FAIL' END AS status, '= 0' AS expected, CAST(all_blank_measure_non_null AS STRING) AS actual FROM edu_access.`03-silver`.deped_personnel_gate_summary_candidate
  UNION ALL SELECT batch_id, 'edu_access.03-silver.deped_personnel_clean_candidate' AS table_name, 'all_blank_measure_flagged' AS check_name, CASE WHEN all_blank_measure_unflagged = 0 THEN 'PASS' ELSE 'FAIL' END AS status, '= 0' AS expected, CAST(all_blank_measure_unflagged AS STRING) AS actual FROM edu_access.`03-silver`.deped_personnel_gate_summary_candidate
  UNION ALL SELECT batch_id, 'edu_access.03-silver.deped_personnel_clean_candidate' AS table_name, 'principal_total_discrepancies' AS check_name, CASE WHEN principal_discrepancies >= 0 THEN 'PASS' ELSE 'PASS' END AS status, '>= 0' AS expected, CAST(principal_discrepancies AS STRING) AS actual FROM edu_access.`03-silver`.deped_personnel_gate_summary_candidate
  UNION ALL SELECT batch_id, 'edu_access.03-silver.deped_personnel_clean_candidate' AS table_name, 'labels_mapped_sector' AS check_name, CASE WHEN unmapped_sector = 0 THEN 'PASS' ELSE 'FAIL' END AS status, '= 0' AS expected, CAST(unmapped_sector AS STRING) AS actual FROM edu_access.`03-silver`.deped_personnel_gate_summary_candidate
  UNION ALL SELECT batch_id, 'edu_access.03-silver.deped_personnel_clean_candidate' AS table_name, 'labels_mapped_school_management' AS check_name, CASE WHEN unmapped_school_management = 0 THEN 'PASS' ELSE 'FAIL' END AS status, '= 0' AS expected, CAST(unmapped_school_management AS STRING) AS actual FROM edu_access.`03-silver`.deped_personnel_gate_summary_candidate
  UNION ALL SELECT batch_id, 'edu_access.03-silver.deped_personnel_clean_candidate' AS table_name, 'labels_mapped_offers_es' AS check_name, CASE WHEN unmapped_offers_es = 0 THEN 'PASS' ELSE 'FAIL' END AS status, '= 0' AS expected, CAST(unmapped_offers_es AS STRING) AS actual FROM edu_access.`03-silver`.deped_personnel_gate_summary_candidate
  UNION ALL SELECT batch_id, 'edu_access.03-silver.deped_personnel_clean_candidate' AS table_name, 'labels_mapped_offers_jhs' AS check_name, CASE WHEN unmapped_offers_jhs = 0 THEN 'PASS' ELSE 'FAIL' END AS status, '= 0' AS expected, CAST(unmapped_offers_jhs AS STRING) AS actual FROM edu_access.`03-silver`.deped_personnel_gate_summary_candidate
  UNION ALL SELECT batch_id, 'edu_access.03-silver.deped_personnel_clean_candidate' AS table_name, 'labels_mapped_offers_shs' AS check_name, CASE WHEN unmapped_offers_shs = 0 THEN 'PASS' ELSE 'FAIL' END AS status, '= 0' AS expected, CAST(unmapped_offers_shs AS STRING) AS actual FROM edu_access.`03-silver`.deped_personnel_gate_summary_candidate
  UNION ALL SELECT batch_id, 'edu_access.03-silver.deped_personnel_quarantine_candidate', 'quarantine_reason_school_id_blank', CASE WHEN school_id_blank = 0 THEN 'PASS' ELSE 'WARN' END, '0', CAST(school_id_blank AS STRING) FROM edu_access.`03-silver`.deped_personnel_gate_summary_candidate
  UNION ALL SELECT batch_id, 'edu_access.03-silver.deped_personnel_quarantine_candidate', 'quarantine_reason_school_id_malformed', CASE WHEN school_id_malformed = 0 THEN 'PASS' ELSE 'WARN' END, '0', CAST(school_id_malformed AS STRING) FROM edu_access.`03-silver`.deped_personnel_gate_summary_candidate
  UNION ALL SELECT batch_id, 'edu_access.03-silver.deped_personnel_quarantine_candidate', 'quarantine_reason_school_id_duplicated', CASE WHEN school_id_duplicated = 0 THEN 'PASS' ELSE 'WARN' END, '0', CAST(school_id_duplicated AS STRING) FROM edu_access.`03-silver`.deped_personnel_gate_summary_candidate
  UNION ALL SELECT batch_id, 'edu_access.03-silver.deped_personnel_quarantine_candidate', 'quarantine_reason_measure_negative', CASE WHEN measure_negative = 0 THEN 'PASS' ELSE 'WARN' END, '0', CAST(measure_negative AS STRING) FROM edu_access.`03-silver`.deped_personnel_gate_summary_candidate
  UNION ALL SELECT batch_id, 'edu_access.03-silver.deped_personnel_quarantine_candidate', 'quarantine_reason_measure_uncastable', CASE WHEN measure_uncastable = 0 THEN 'PASS' ELSE 'WARN' END, '0', CAST(measure_uncastable AS STRING) FROM edu_access.`03-silver`.deped_personnel_gate_summary_candidate
  UNION ALL SELECT batch_id, 'edu_access.03-silver.deped_personnel_quarantine_candidate', 'quarantine_reason_measure_above_int_max', CASE WHEN measure_above_int_max = 0 THEN 'PASS' ELSE 'WARN' END, '0', CAST(measure_above_int_max AS STRING) FROM edu_access.`03-silver`.deped_personnel_gate_summary_candidate
  UNION ALL SELECT batch_id, 'edu_access.03-silver.deped_personnel_quarantine_candidate', 'quarantine_reason_measure_outside_public_scope', CASE WHEN measure_outside_public_scope = 0 THEN 'PASS' ELSE 'WARN' END, '0', CAST(measure_outside_public_scope AS STRING) FROM edu_access.`03-silver`.deped_personnel_gate_summary_candidate
  UNION ALL SELECT batch_id, 'edu_access.03-silver.deped_personnel_quarantine_candidate', 'quarantine_reason_measure_outside_offered_level', CASE WHEN measure_outside_offered_level = 0 THEN 'PASS' ELSE 'WARN' END, '0', CAST(measure_outside_offered_level AS STRING) FROM edu_access.`03-silver`.deped_personnel_gate_summary_candidate
  UNION ALL SELECT batch_id, 'edu_access.03-silver.deped_personnel_quarantine_candidate', 'quarantine_rate', CASE WHEN quarantine_rows = 0 THEN 'PASS' WHEN quarantine_rows * 100 > bronze_rows THEN 'FAIL' ELSE 'WARN' END, '0 (FAIL above 1% of ' || CAST(bronze_rows AS STRING) || ')', CAST(quarantine_rows AS STRING) FROM edu_access.`03-silver`.deped_personnel_gate_summary_candidate
) AS results;

MERGE INTO edu_access.`01-control`.pipeline_runs AS t USING (SELECT :run_id AS run_id, COUNT_IF(status = 'FAIL') AS fails FROM edu_access.`01-control`.data_quality_results WHERE run_id = :run_id AND source_id = 'deped_personnel' AND layer = 'silver' AND checked_at_utc >= session.silver_gate_started_at_utc) AS s
ON t.run_id = s.run_id AND t.pipeline_name = 'silver_build' AND t.source_id = 'deped_personnel' WHEN MATCHED AND s.fails > 0 THEN UPDATE SET status = 'failed', finished_at_utc = current_timestamp(), failure_stage = 'gate', error_message = CAST(s.fails AS STRING) || ' FAIL result(s) in data_quality_results';

SELECT CASE WHEN COUNT(*) > 0 THEN raise_error('Silver gate failed for deped_personnel: ' || CAST(COUNT(*) AS STRING) || ' FAIL result(s)') END FROM edu_access.`01-control`.data_quality_results WHERE run_id = :run_id AND source_id = 'deped_personnel' AND layer = 'silver' AND status = 'FAIL' AND checked_at_utc >= session.silver_gate_started_at_utc;

CREATE OR REPLACE TABLE edu_access.`03-silver`.deped_personnel_quarantine USING DELTA AS SELECT * FROM edu_access.`03-silver`.deped_personnel_quarantine_candidate;
ALTER TABLE edu_access.`03-silver`.deped_personnel_quarantine OWNER TO `reached-hq`;

CREATE OR REPLACE TABLE edu_access.`03-silver`.deped_personnel_clean USING DELTA AS SELECT * FROM edu_access.`03-silver`.deped_personnel_clean_candidate;
ALTER TABLE edu_access.`03-silver`.deped_personnel_clean OWNER TO `reached-hq`;

MERGE INTO edu_access.`01-control`.pipeline_runs AS t USING (SELECT :run_id AS run_id) AS s ON t.run_id = s.run_id AND t.pipeline_name = 'silver_build' AND t.source_id = 'deped_personnel' WHEN MATCHED THEN UPDATE SET status = 'succeeded', finished_at_utc = current_timestamp(), failure_stage = NULL, error_message = NULL;

DROP TABLE IF EXISTS edu_access.`03-silver`.deped_personnel_gate_summary_candidate;
